const sourceMap = new Map(HISTORY_MODERN_SOURCES.map(item => [item.id, item]));
function refs(...keys: string[]) { return keys.map(key => { const item = sourceMap.get(sid(key)); if (!item) throw new Error(`Unknown history source: ${key}`); return item; }); }
const block = (text: string, evidence: HistoryBlock["evidence"], ...keys: string[]): HistoryBlock => ({ text, evidence, sourceIds: keys.map(sid) });
type ChoiceInput = readonly [string, string, boolean, string];
const choices = (items: readonly ChoiceInput[]): HistoryChoice[] => items.map(([id, text, correct, feedback]) => ({ id, text, correct, feedback }));
function step(id: string, prompt: string, items: readonly ChoiceInput[], keys: string[], reasons?: readonly ChoiceInput[]): HistoryStep {
  return { id, prompt, choices: choices(items), sourceIds: keys.map(sid), ...(reasons ? { reasonPrompt: "Quelle preuve justifie votre choix ?", reasons: choices(reasons) } : {}) };
}
function exercise(id: string, kind: HistoryActivity["kind"], title: string, evaluates: string, scenario: string, steps: readonly HistoryStep[], takeaway: string, fictional = false, documents?: HistoryActivity["documents"]): HistoryActivity {
  return { id, kind, title, evaluates, scenario, steps, takeaway, fictional, ...(documents ? { documents } : {}) };
}

