function question(chapterId: string, number: number, lesson: number, prompt: string, options: readonly string[], keys: string[], difficulty: HistoryQuizQuestion["difficulty"] = "medium", buddyCodes?: string[]): HistoryQuizQuestion {
  return { id: `history-${chapterId}-q${String(number).padStart(2, "0")}`, chapterId, prompt, options: options.map((text, index) => ({ id: "abcd"[index], text })), difficulty, lessonId: "history", sectionId: `history-${chapterId}-${lesson}`, sources: refs(...keys), ...(buddyCodes ? { buddyCodes } : {}) };
}
